const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location and time period
  const needles = ee.Geometry.Point([-114.614, 34.848]);
  const startDate = '2017-06-15';
  const endDate = '2017-06-22';

  // 2. Load MODIS Land Surface Temperature data (Terra and Aqua for day/night coverage)
  const modis = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(needles)
    .select(['LST_Day_1km', 'QC_Day']);

  const modisSize = modis.size().getInfo();
  console.log(`MODIS images found: ${modisSize}`);

  if (modisSize === 0) {
    console.log('No MODIS data available for the period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Process temperature data
  // Convert from Kelvin to Celsius (MODIS LST is in Kelvin * 0.02)
  const tempCollection = modis.map(function(img) {
    const lst = img.select('LST_Day_1km').multiply(0.02).subtract(273.15);
    const qc = img.select('QC_Day');
    // Mask poor quality pixels (QC bits 0-1 should be 00 for good quality)
    const goodQuality = qc.bitwiseAnd(3).eq(0);
    return lst.updateMask(goodQuality);
  });

  // 4. Get maximum temperature across all images
  const maxTemp = tempCollection.max();

  // 5. Extract temperature value at Needles
  const result = maxTemp.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: needles,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const maxTempC = result.LST_Day_1km;

  // 6. Check pixel count to ensure valid data
  const pixelCount = maxTemp.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: needles,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const validPixels = pixelCount.LST_Day_1km || 0;

  console.log(`Valid pixels: ${validPixels}`);

  if (validPixels === 0) {
    console.log('No valid pixels after quality masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (maxTempC === null || maxTempC === undefined || isNaN(maxTempC)) {
    console.log('Temperature calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check for unrealistic temperature values
  if (maxTempC > 100 || maxTempC < -100) {
    console.log(`Unrealistic temperature: ${maxTempC.toFixed(2)}C`);
    console.log('<answer>C3</answer>');
    return;
  }

  const maxTempF = (maxTempC * 9/5) + 32;
  const threshold = 115.0;

  console.log(`Maximum temperature: ${maxTempC.toFixed(2)}C (${maxTempF.toFixed(2)}F)`);
  console.log(`Threshold: ${threshold}F`);

  if (maxTempF >= threshold) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
